// Prepara nombres de carpeta, README y variables para el flujo.
// Lee desde $input los datos del webhook.

const MESES = {
  '01': 'Enero', '02': 'Febrero', '03': 'Marzo', '04': 'Abril',
  '05': 'Mayo', '06': 'Junio', '07': 'Julio', '08': 'Agosto',
  '09': 'Septiembre', '10': 'Octubre', '11': 'Noviembre', '12': 'Diciembre'
};

const body = $input.first().json.body || $input.first().json;

const fecha = body.fecha_ejecucion; // 'YYYY-MM-DD'
const anio = fecha.slice(0, 4);
const mes = fecha.slice(5, 7);
const nombreMes = MESES[mes] || mes;

const slug = (s) => (s || '').toString()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // sin tildes
  .replace(/[^a-zA-Z0-9]+/g, '') // sin espacios ni símbolos
  .trim();

const proveedorSlug = slug(body.proveedor);
const categoriaSlug = slug(body.categoria);
const sedes = (body.sedes || []).join('-');

const mesFolderName = `${anio}-${mes} ${nombreMes}`;
const jornadaFolderName = `${fecha}_${proveedorSlug}_${categoriaSlug}_${sedes}`;

// Armo el README de la jornada
const mantenimientos = body.mantenimientos || [];
const filaMnt = mantenimientos.map((m, i) =>
  ` ${String(i + 1).padStart(2, ' ')} | ${m.equipo_codigo.padEnd(10)} | ${(m.equipo_nombre || '').padEnd(40)} | ${(m.sede || '').padEnd(4)} | ${m.mnt_codigo}`
).join('\n');

const readme = `================================================================
JORNADA DE MANTENIMIENTO
================================================================

DATOS GENERALES
---------------
Fecha de ejecución : ${fecha}
Hora de inicio    : ${body.hora_inicio || '-'}
Hora de fin       : ${body.hora_fin || '-'}
Proveedor         : ${body.proveedor || '-'}
Técnico responsable: ${body.tecnico || '-'}
Categoría         : ${body.categoria || '-'}
Sedes atendidas   : ${(body.sedes || []).join(', ')}


EQUIPOS CUBIERTOS (${mantenimientos.length})
-------------------
 # | Equipo    | Nombre / Ubicación                     | Sede | Código MANTIX
---|-----------|------------------------------------------|------|---------------
${filaMnt}


DOCUMENTOS ADJUNTOS EN ESTA CARPETA
-----------------------------------
[ ] 00_INFORME_CONSOLIDADO.pdf   (informe único entregado por el proveedor)
[ ] 02_Evidencias_Fotograficas/  (fotos antes/después por equipo)
[ ] 03_Checklists_Firmados/      (checklist firmado por equipo)
[ ] 04_Actas_Firmas/             (acta de entrega y recibido)


OBSERVACIONES
-------------
${body.observaciones || '-'}


================================================================
Generado automáticamente por workflow n8n (Mantix - Evidencias Drive).
================================================================
`;

return [{ json: {
  anio,
  mes,
  nombreMes,
  mesFolderName,
  jornadaFolderName,
  readme,
  // ID de la raíz '2026' (hard-coded; cambiar si el año avanza)
  anioFolderId: '14L1NVkA6jC9kvvPSYH2pWKKg5bb3G8lv',
  // Metadatos para el response
  payload: body
}}];

// Guardo el folderId de la jornada y propago los campos para los próximos nodos
const jornada = $input.first().json;
const prev = $('Prepare names + README').first().json;

return [{ json: {
  ...prev,
  jornadaFolderId: jornada.id,
  jornadaFolderUrl: `https://drive.google.com/drive/folders/${jornada.id}`
}}];
